@DisplayName("Phylax RBAC store")
class PhylaxUnitTest {
  private static final String GRANTS = """
      [{"rolename":"admin","allowedScopes":["tenant:read"],
        "restrictedFields":{"detail":["tenant:secret"]}},
       {"rolename":"-","allowedScopes":["public:list"],"restrictedFields":{}},
       {"rolename":"other","allowedScopes":["tenant:delete"],
        "restrictedFields":{"detail":["tenant:name"]}}]
      """;

  private ObjectMapper mapper;
  private HttpClient client;
  private ScheduledExecutorService executor;
  private Phylax phylax;
  private final List<Runnable> scheduled = new ArrayList<>();

  @BeforeEach
  void setUp() throws Exception {
    mapper = spy(new ObjectMapper());
    client = mock(HttpClient.class);
    executor = mock(ScheduledExecutorService.class);
    when(executor.schedule(any(Runnable.class), anyLong(), any(TimeUnit.class)))
        .thenAnswer(invocation -> {
          scheduled.add(invocation.getArgument(0));
          return null;
        });
    phylax = new Phylax(mapper, "phylax", "key", "aud", "http://phylax/scopes",
        "http://phylax/schema", "http://phylax/grants");
    replace("client", client);
    replace("executorService", executor);
  }

  @AfterEach
  void clearInterruption() {
    Thread.interrupted();
  }

  private void replace(String name, Object value) throws ReflectiveOperationException {
    Field field = Phylax.class.getDeclaredField(name);
    field.setAccessible(true);
    field.set(phylax, value);
  }

  @SuppressWarnings("unchecked")
  private static HttpResponse<String> response(int status, String body) {
    HttpResponse<String> response = mock(HttpResponse.class);
    when(response.statusCode()).thenReturn(status);
    when(response.body()).thenReturn(body);
    return response;
  }

  private void register() {
    ResourceDescription tenant =
        ResourceDescription.builder().name("tenant").description("Tenants").build();
    ResourceDescription user =
        ResourceDescription.builder().name("user").description("Users").build();
    phylax.registerResourceAction(tenant,
        ScopeDescription.builder().name("read").description("Read").kind(Kind.values()[0]).build());
    phylax.registerResourceAction(tenant, ScopeDescription.builder().name("write")
        .description("Write").kind(Kind.values()[0]).build());
    phylax.registerResourceAction(user,
        ScopeDescription.builder().name("read").description("Read").kind(Kind.values()[0]).build());
    phylax.registerResourceField(tenant,
        FieldDescription.builder().name("name").description("Name").build());
    phylax.registerResourceField(tenant,
        FieldDescription.builder().name("secret").description("Secret").build());
  }

  @Test
  @DisplayName("Should be active only for the phylax model")
  void shouldBeActiveOnlyForPhylaxModel() {
    assertTrue(phylax.isActive());
    assertFalse(new Phylax(mapper, "keycloak", "", "", "", "", "").isActive());
  }

  @Nested
  @DisplayName("Startup registration")
  class Registration {

    @Test
    @DisplayName("Should send grouped scopes and properties and clear them once accepted")
    void shouldSendGroupedRegistrations() throws Exception {
      // Arrange — registrations for two resources, an accepting server and a payload recorder
      register();
      doReturn(response(200, "")).when(client).send(any(), any());
      List<String> payloads = new ArrayList<>();
      doAnswer(invocation -> {
        String json = (String) invocation.callRealMethod();
        payloads.add(json);
        return json;
      }).when(mapper).writeValueAsString(any());

      // Act — run the startup hook twice
      phylax.complete(null);
      phylax.complete(null);

      // Assert — the first run sends the grouped payloads and the second has nothing pending
      assertEquals(4, payloads.size());
      JsonNode scopes = new ObjectMapper().readTree(payloads.get(0));
      assertEquals(2, scopes.size());
      for (JsonNode resource : scopes) {
        int expected = "tenant".equals(resource.at("/resource/name").asText()) ? 2 : 1;
        assertEquals(expected, resource.get("scopes").size());
      }
      JsonNode properties = new ObjectMapper().readTree(payloads.get(1));
      assertEquals(1, properties.size());
      assertEquals(2, properties.get(0).get("properties").size());
      assertEquals("[]", payloads.get(2));
      assertEquals("[]", payloads.get(3));
      verify(executor, never()).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));
    }

    @Test
    @DisplayName("Should retry rejected registrations later and succeed")
    void shouldRetryRejectedRegistrations() throws Exception {
      // Arrange — the server rejects the first calls and accepts the retries
      register();
      HttpResponse<String> rejected = response(500, "boom");
      HttpResponse<String> accepted = response(201, "");
      doReturn(rejected, rejected, accepted, accepted).when(client).send(any(), any());

      // Act — run startup and then the scheduled retries
      phylax.complete(null);
      scheduled.forEach(Runnable::run);

      // Assert — both registrations were retried once
      assertEquals(2, scheduled.size());
      verify(executor, times(2)).schedule(any(Runnable.class), eq(10L), eq(TimeUnit.SECONDS));
      verify(client, times(4)).send(any(), any());
    }

    @Test
    @DisplayName("Should log retries that fail again")
    void shouldLogFailedRetries() throws Exception {
      register();
      doThrow(new IOException("down")).when(client).send(any(), any());

      phylax.complete(null);
      scheduled.forEach(Runnable::run);

      assertEquals(2, scheduled.size());
      verify(client, times(4)).send(any(), any());
    }

    @Test
    @DisplayName("Should restore the interruption flag when a retry is interrupted")
    void shouldRestoreInterruptionOnRetry() throws Exception {
      register();
      doThrow(new IOException("down"), new IOException("down"), new InterruptedException("stop"))
          .when(client).send(any(), any());

      phylax.complete(null);
      scheduled.get(0).run();

      assertTrue(Thread.interrupted(), "interrupted retry must re-flag the thread");
      doThrow(new InterruptedException("stop")).when(client).send(any(), any());
      scheduled.get(1).run();
      assertTrue(Thread.interrupted(), "interrupted retry must re-flag the thread");
    }

    @Test
    @DisplayName("Should restore the interruption flag when registration is interrupted")
    void shouldRestoreInterruptionOnRegistration() throws Exception {
      register();
      doThrow(new InterruptedException("stop")).when(client).send(any(), any());

      phylax.complete(null);

      assertTrue(Thread.interrupted(), "interrupted registration must re-flag the thread");
      verify(executor, never()).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));
    }

    @Test
    @DisplayName("Should schedule a retry when the registration URL is invalid")
    void shouldRetryOnInvalidUrl() {
      Phylax invalid = new Phylax(mapper, "phylax", "key", "aud", "http://bad url",
          "http://bad url", "http://phylax/grants");
      try {
        Field field = Phylax.class.getDeclaredField("executorService");
        field.setAccessible(true);
        field.set(invalid, executor);
      } catch (ReflectiveOperationException e) {
        throw new IllegalStateException(e);
      }

      invalid.complete(null);

      assertEquals(2, scheduled.size());
    }
  }

  @Nested
  @DisplayName("Grant checks")
  class Grants {
    private final Actor admin = ActorImpl.builder().groups(List.of("admin")).build();

    @Test
    @DisplayName("Should grant scopes of the actor groups plus the public role and cache them")
    void shouldGrantScopesAndCache() throws Exception {
      // Arrange — the server returns grants for several roles
      doReturn(response(200, GRANTS)).when(client).send(any(), any());

      // Act — check scopes and properties
      ScopeAllowList scopes = phylax.checkRoleScopes(admin);
      FieldGrantList fields = phylax.checkRoleProperties(admin);

      // Assert — only matching roles apply and the grants are fetched once
      assertTrue(scopes.allowed("tenant", "read"));
      assertTrue(scopes.allowed("public", "list"));
      assertFalse(scopes.allowed("tenant", "delete"));
      assertEquals(List.of("secret"), fields.inaccessiblesFor("tenant", "detail"));
      verify(client, times(1)).send(any(), any());
    }

    @Test
    @DisplayName("Should fetch the grants again once the cache expires")
    void shouldRefreshExpiredGrants() throws Exception {
      doReturn(response(200, GRANTS)).when(client).send(any(), any());
      phylax.checkRoleScopes(admin);

      replace("scopesExpiration", OffsetDateTime.now().minusMinutes(1));
      phylax.checkRoleScopes(admin);

      verify(client, times(2)).send(any(), any());
    }

    @Test
    @DisplayName("Should fail when the grants endpoint rejects the call")
    void shouldFailOnRejectedCall() throws Exception {
      doReturn(response(403, "forbidden")).when(client).send(any(), any());
      assertThrows(IllegalArgumentException.class, () -> phylax.checkRoleScopes(admin));
    }

    @Test
    @DisplayName("Should fail when the grants endpoint is unreachable")
    void shouldFailOnUnreachableEndpoint() throws Exception {
      doThrow(new IOException("down")).when(client).send(any(), any());
      assertThrows(IllegalArgumentException.class, () -> phylax.checkRoleProperties(admin));
    }

    @Test
    @DisplayName("Should fail and restore the interruption flag when interrupted")
    void shouldFailOnInterruption() throws Exception {
      doThrow(new InterruptedException("stop")).when(client).send(any(), any());
      assertThrows(IllegalArgumentException.class, () -> phylax.checkRoleScopes(admin));
      assertTrue(Thread.interrupted());
    }

    @Test
    @DisplayName("Should fail when the grants response is not valid JSON")
    void shouldFailOnInvalidJson() throws Exception {
      doReturn(response(200, "{not json")).when(client).send(any(), any());
      assertThrows(IllegalArgumentException.class, () -> phylax.checkRoleScopes(admin));
    }
  }
}
